use std::fs;

pub fn list(root: &str) -> Result<Vec<(i32, String)>, i32> {
    let mut files = Vec::new();
    let entries = fs::read_dir(root).map_err(|_| 1)?;
    for entry in entries {
        let entry = entry.map_err(|_| 1)?;
        let name = entry.file_name().to_string_lossy().into_owned();
        if name.len() != 13 || !name.starts_with('d') || !name.ends_with(".tbl") {
            continue;
        }
        let digits = &name[1..9];
        if !digits.bytes().all(|b| b.is_ascii_digit()) || !entry.file_type().map_err(|_| 1)?.is_file() {
            continue;
        }
        if let Ok(day) = digits.parse::<i32>() {
            files.push((day, entry.path().to_string_lossy().into_owned()));
        }
    }
    files.sort_by_key(|x| x.0);
    Ok(files)
