pub fn gait(taken: i32, packed: &[(i32, String)]) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    if taken <= 0 || packed.is_empty() {
        return 1;
    }

    // This count is deliberately taken from the live inputs, independently of
    // ledger.json and the staged count.  Also verify every restored copy.
    let mut matched = 0;
    for (day, _) in packed {
