            Ok(value) => value,
            Err(_) => return 1,
        };
        let restored_rows = match rows(&restored) {
            Ok(value) => value,
            Err(_) => return 1,
        };
        if source_rows != restored_rows {
            return 1;
        }
        matched += source_rows;
    }
    if matched != taken {
        return 1;
    }
    if emit("/app/daywell", matched, taken).is_err() {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
